content.css:
.navigationMenuRoot {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  position: relative;
  background: #ffffff;
}
/* ---- Menu container ---------------------------------------------------- */
.nm-menu {
  width: 100%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  box-sizing: border-box;
  padding: 8px 6px;
}
.nm-menu::-webkit-scrollbar {
  width: 4px;
}
.nm-menu::-webkit-scrollbar-track {
  background: transparent;
}
.nm-menu::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 2px;
}
/* ---- Group header ------------------------------------------------------ */
.nm-group-header {
  display: flex;
  align-items: center;
  padding: 0 12px;
  cursor: pointer;
  user-select: none;
  font-weight: 600;
  letter-spacing: 0.05em;
  margin-top: 8px;
  transition: opacity 0.15s ease;
}
.nm-group-header:hover {
  opacity: 0.8;
}
.nm-chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  margin-right: 6px;
  flex-shrink: 0;
}
.nm-group-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* ---- Menu item --------------------------------------------------------- */
.nm-item {
  display: flex;
  align-items: center;
  padding-right: 12px;
  cursor: pointer;
  user-select: none;
  position: relative;
  margin: 2px 4px;
  transition: background 0.12s ease, color 0.12s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nm-accent {
  position: absolute;
  left: 0;
  top: 15%;
  bottom: 15%;
  width: 3px;
}
.nm-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin-right: 10px;
  flex-shrink: 0;
}
.nm-icon svg {
  display: block;
}
.nm-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.4;
}
/* ---- Landing page ------------------------------------------------------ */
.nm-landing {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  padding: 16px;
  box-sizing: border-box;
}
.nm-landing-card {
  border: none;
  box-shadow: none;
  border-radius: 8px;
  padding: 40px 56px;
  text-align: center;
  max-width: 480px;
  background: #ffffff;
}
.nm-landing-logo {
  width: 120px;
  height: auto;
  margin: 0 auto 28px;
  display: block;
  border-radius: 16px;
  overflow: hidden;
}
.nm-landing-title {
  font-size: 20px;
  font-weight: 600;
  color: #0f172a;
  margin-bottom: 16px;
}
.nm-landing-desc {
  font-size: 13px;
  color: #475569;
  line-height: 1.6;
}
.nm-landing-desc b {
  color: #1e293b;
  font-weight: 600;
}
.nm-landing-sep {
  height: 1px;
  background: #e2e8f0;
  margin: 28px auto 20px;
  width: 80%;
}
.nm-landing-meta {
  font-size: 12px;
  color: #94a3b8;
  line-height: 1.8;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
